
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b86_r_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b86_r", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243666374747691e+00, -4.161005525771591e+00, -4.045243816854408e+00, -3.885025411061317e+00, -3.667008412708952e+00, -3.377498252526461e+00, -3.006312060373002e+00, -2.553821583011801e+00, -2.040686182980618e+00, -1.513202283425987e+00, -1.021875294792665e+00, -6.943434312587882e-01, -5.966349470389528e-01, -4.891796114606818e-01, -3.529657568898119e-01, -2.268061252483222e-01, -1.317067824370003e-01, -6.081474531495572e-02, -1.954297467181880e-02, -4.305140089319123e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


